using IDSFintech.Api.DTOs; using IDSFintech.Api.Repositories; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; namespace IDSFintech.Api.Controllers; [ApiController,Authorize,Route("api/[controller]")] public sealed class ModulesController(IPortalRepository r):ControllerBase { [HttpGet] public async Task<IActionResult> Get(int? productId)=>Ok(new ApiResponse<object>("Modules retrieved.",await r.ModulesAsync(productId))); }
